533	                    () -> new Payment(invoice.getId(), request.amount(), request.date()));
534	        }
535	        if (!currencies.exists(currency)) {
536	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Unknown currency");
537	        }
538	        BigDecimal settles = fxRates.convert(currency, invoice.getCurrency(), request.date(), request.amount())
539	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
540	                        "No exchange rate for " + currency + " to " + invoice.getCurrency() + " on " + request.date()));
