658	    private static <A> void requireDistinct(List<A> allocations, Function<A, Long> invoiceId) {
659	        Set<Long> seen = new HashSet<>();
660	        for (A a : allocations) {
661	            if (!seen.add(invoiceId.apply(a))) {
662	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Each invoice may be paid only once");
663	            }
664	        }
665	    }
