667	    private PaymentResponse apply(Invoice invoice, BigDecimal amount, Supplier<Payment> payment) {
668	        if (invoice.getStatus() == InvoiceStatus.DRAFT) {
669	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Send the invoice before recording a payment");
670	        }
671	        if (invoice.getStatus() == InvoiceStatus.VOID) {
672	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been cancelled");
673	        }
674	        if (invoice.getStatus() == InvoiceStatus.WRITTEN_OFF) {
675	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been written off");
676	        }
677	        if (!invoice.getStatus().isOwing()) {
678	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice is already paid");
679	        }
680	        BigDecimal paid = payments.sumAmountByInvoiceId(invoice.getId()).add(amount);
681	        BigDecimal credited = creditNotes.sumAmountByInvoiceId(invoice.getId());
682	        BigDecimal settled = paid.add(credited);
683	        if (settled.compareTo(invoice.getAmount()) > 0) {
684	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Payment is more than the balance due");
685	        }
686	        Payment saved = payments.saveAndFlush(payment.get());
687	        if (invoice.getDueDate() != null && saved.getDate().isBefore(invoice.getDueDate())) {
688	            invoice.takeRebateIfEarned(payments.sumAmountByInvoiceIdPaidBefore(invoice.getId(), invoice.getDueDate()),
689	                    credited);
690	        }
691	        invoice.applySettledTotals(paid, credited);
692	        invoices.flush();
693	        audit.record("PAYMENT_RECORDED id=" + saved.getId() + " amount=" + saved.getAmount().toPlainString()
694	                + (saved.getPaidCurrency() == null ? ""
695	                        : " paid=" + saved.getPaidAmount().toPlainString() + " " + saved.getPaidCurrency()));
696	        return PaymentResponse.from(saved);
697	    }
